#requires -Version 5.1
[CmdletBinding()]
param(
    [ValidateSet('Install','Repair','Verify','Preflight','Uninstall','SelfTest','DesktopDatabaseRepair')]
    [string]$Action = 'Install',

    [ValidateSet('Auto','Desktop','Docker','BareMetal','Remote')]
    [string]$Platform = 'Auto',

    [string]$BaseUrl,
    [string]$TokenFile,
    [switch]$PromptForCredential,
    [string]$Email,
    [string]$PasswordFile,
    [string]$CaCertificate,
    [switch]$InsecureTls,
    [double]$RequestTimeout = 15,
    [double]$StartupTimeout = 300,
    [double]$RouteTimeout = 180,
    [ValidateSet('Never','OnFailure','Always')]
    [string]$RestartPolicy = 'OnFailure',
    [switch]$NoStartBackend,
    [switch]$NoRollback,
    [switch]$KeepLegacyDisabled,
    [string]$ReportPath = '.\vut-ai-tutor-universal-report.json',
    [string]$BackupDir,
    [string]$DesktopInstallRoot,
    [string]$DesktopConfigRoot,
    [string]$DesktopExecutable,
    [ValidateSet('Auto','Docker','Podman')]
    [string]$ContainerEngine = 'Auto',
    [string]$ContainerName,
    [string]$ServiceName,
    [string]$RestartCommand,
    [string]$PythonPath,
    [switch]$AllowPlatformMutation,
    [switch]$KeepPayloadDirectory
)

Set-StrictMode -Version Latest
$ErrorActionPreference = 'Stop'
$InstallerVersion = '2.0.6'
$RuntimeVersion = '1.26.5'
# CmdletBinding already supplies the common -Debug switch. Redeclaring it
# causes ParameterNameAlreadyExistsForCommand before the script can run.
$DiagnosticsEnabled = $PSBoundParameters.ContainsKey('Debug') -and [bool]$PSBoundParameters['Debug']

$ManagerPayload = ''
$BootstrapPayload = ''
$PipePayload = ''
$DesktopRepairPayload = ''
$ExpectedManagerSha = '9b771751f0d0347683cc6cf2a4ecc86bc8f42b64b5bb19228a8c89d36f4ee564'
$ExpectedBootstrapSha = 'bdf315b89c38fbc1417e04936871498ea5ac64f59d0eb0f46eada4b4572ac32f'
$ExpectedPipeSha = '9bebab54e1f8cbe841973c4ab06e2e88358542027233f64f4ea7a4f691603893'
$ExpectedDesktopRepairSha = 'dd2dfd552ed54f963389e2ac90a91f27e8fbb280c3c88cc59f14c3d83e3c4a03'

function Get-Sha256([string]$Path) {
    return (Get-FileHash -LiteralPath $Path -Algorithm SHA256).Hash.ToLowerInvariant()
}

function Expand-EmbeddedPayload {
    param(
        [Parameter(Mandatory=$true)][string]$Base64Gzip,
        [Parameter(Mandatory=$true)][string]$Destination,
        [Parameter(Mandatory=$true)][string]$ExpectedSha
    )
    $compressed = [Convert]::FromBase64String($Base64Gzip)
    $input = New-Object System.IO.MemoryStream(,$compressed)
    try {
        $gzip = New-Object System.IO.Compression.GZipStream($input,[System.IO.Compression.CompressionMode]::Decompress)
        try {
            $output = [System.IO.File]::Create($Destination)
            try { $gzip.CopyTo($output) } finally { $output.Dispose() }
        } finally { $gzip.Dispose() }
    } finally { $input.Dispose() }
    $actual = Get-Sha256 $Destination
    if ($actual -ne $ExpectedSha) {
        throw ('Embedded payload hash mismatch for {0}: expected {1}, got {2}' -f $Destination,$ExpectedSha,$actual)
    }
}

function Resolve-Python {
    param([string]$Requested)
    if ($Requested) {
        $resolved = (Resolve-Path -LiteralPath $Requested -ErrorAction Stop).Path
        return $resolved
    }
    foreach ($candidate in @('py.exe','python.exe','python3.exe','python3','python')) {
        $command = Get-Command $candidate -ErrorAction SilentlyContinue
        if ($command) { return $command.Source }
    }
    throw 'Python 3.11 or newer was not found. Supply -PythonPath.'
}

function Invoke-CapturedProcess {
    param(
        [Parameter(Mandatory=$true)][string]$FileName,
        [Parameter(Mandatory=$true)][string[]]$Arguments,
        [hashtable]$Environment = @{}
    )
    $psi = New-Object System.Diagnostics.ProcessStartInfo
    $psi.FileName = $FileName
    $psi.UseShellExecute = $false
    $psi.RedirectStandardOutput = $true
    $psi.RedirectStandardError = $true
    $psi.CreateNoWindow = $true
    $quoted = foreach ($arg in $Arguments) {
        if ($arg -notmatch '[\s"]') { $arg }
        else { '"' + ($arg -replace '(\\*)"','$1$1\"' -replace '(\\+)$','$1$1') + '"' }
    }
    $psi.Arguments = ($quoted -join ' ')
    foreach ($key in $Environment.Keys) {
        if ($null -eq $Environment[$key]) { $psi.EnvironmentVariables.Remove([string]$key) }
        else { $psi.EnvironmentVariables[[string]$key] = [string]$Environment[$key] }
    }
    $process = New-Object System.Diagnostics.Process
    $process.StartInfo = $psi
    if (-not $process.Start()) { throw ('Could not start {0}' -f $FileName) }
    $stdoutTask = $process.StandardOutput.ReadToEndAsync()
    $stderrTask = $process.StandardError.ReadToEndAsync()
    $process.WaitForExit()
    $stdout = $stdoutTask.Result
    $stderr = $stderrTask.Result
    if ($stdout) { [Console]::Out.Write($stdout) }
    if ($stderr) { [Console]::Error.Write($stderr) }
    return [pscustomobject]@{ ExitCode=$process.ExitCode; StdOut=$stdout; StdErr=$stderr }
}

$payloadDir = Join-Path ([System.IO.Path]::GetTempPath()) ('vut-ai-tutor-universal-2.0.6-' + [Guid]::NewGuid().ToString('N'))
[System.IO.Directory]::CreateDirectory($payloadDir) | Out-Null
$managerPath = Join-Path $payloadDir 'vut_ai_tutor_universal_installer_v2.0.6.py'
$bootstrapPath = Join-Path $payloadDir 'vut_ai_tutor_bootstrap_v1.26.5.py'
$pipePath = Join-Path $payloadDir 'vut_ai_tutor_pipe_v1.26.5.py'
$desktopRepairPath = Join-Path $payloadDir 'repair-install-vut-ai-tutor-v1.26.5-desktop.ps1'

try {
    Expand-EmbeddedPayload $ManagerPayload $managerPath $ExpectedManagerSha
    Expand-EmbeddedPayload $BootstrapPayload $bootstrapPath $ExpectedBootstrapSha
    Expand-EmbeddedPayload $PipePayload $pipePath $ExpectedPipeSha
    Expand-EmbeddedPayload $DesktopRepairPayload $desktopRepairPath $ExpectedDesktopRepairSha

    $python = Resolve-Python $PythonPath
    Write-Host ('[INFO] Universal installer {0}; known-good Tutor runtime {1}.' -f $InstallerVersion,$RuntimeVersion)
    Write-Host ('[INFO] Python: {0}' -f $python)

    if ([System.IO.Path]::IsPathRooted($ReportPath)) { $resolvedReport = [System.IO.Path]::GetFullPath($ReportPath) } else { $resolvedReport = [System.IO.Path]::GetFullPath((Join-Path (Get-Location) $ReportPath)) }
    if ($Action -eq 'DesktopDatabaseRepair') {
        if ($Platform -notin @('Auto','Desktop')) { throw 'DesktopDatabaseRepair is valid only for Desktop.' }
        if (-not $AllowPlatformMutation) { throw 'DesktopDatabaseRepair requires explicit -AllowPlatformMutation.' }
        if (-not $DesktopInstallRoot) { throw 'DesktopDatabaseRepair requires -DesktopInstallRoot.' }
        $repairArgs = @('-NoProfile','-ExecutionPolicy','Bypass','-File',$desktopRepairPath,'-Mode','DatabaseRepair','-Target','Desktop','-DesktopInstallRoot',$DesktopInstallRoot,'-StopDesktopProcesses','-PythonPath',$python,'-ReportPath',$resolvedReport)
        $result = Invoke-CapturedProcess -FileName 'powershell.exe' -Arguments $repairArgs
        if ($result.ExitCode -ne 0) { throw ('Desktop database repair failed with exit code {0}.' -f $result.ExitCode) }
        exit 0
    }

    $credential = $null
    $environment = @{}
    if ($PromptForCredential) {
        $credential = Get-Credential -Message 'Open WebUI administrator credentials'
        $environment['VUT_INSTALL_EMAIL'] = $credential.UserName
        $environment['VUT_INSTALL_PASSWORD'] = $credential.GetNetworkCredential().Password
    }

    $actionMap = @{ Install='install'; Repair='repair'; Verify='verify'; Preflight='preflight'; Uninstall='uninstall'; SelfTest='self-test' }
    $platformMap = @{ Auto='auto'; Desktop='desktop'; Docker='docker'; BareMetal='baremetal'; Remote='remote' }
    $restartMap = @{ Never='never'; OnFailure='on-failure'; Always='always' }
    $engineMap = @{ Auto='auto'; Docker='docker'; Podman='podman' }
    $config = [ordered]@{
        action = $actionMap[$Action]
        platform = $platformMap[$Platform]
        base_url = $BaseUrl
        token_file = $TokenFile
        email = $Email
        password_file = $PasswordFile
        ca_certificate = $CaCertificate
        insecure_tls = [bool]$InsecureTls
        request_timeout = $RequestTimeout
        startup_timeout = $StartupTimeout
        route_timeout = $RouteTimeout
        restart_policy = $restartMap[$RestartPolicy]
        start_backend = -not [bool]$NoStartBackend
        no_rollback = [bool]$NoRollback
        keep_legacy_disabled = [bool]$KeepLegacyDisabled
        report_path = $resolvedReport
        backup_dir = $BackupDir
        bootstrap_path = $bootstrapPath
        pipe_path = $pipePath
        desktop_install_root = $DesktopInstallRoot
        desktop_config_root = $DesktopConfigRoot
        desktop_executable = $DesktopExecutable
        container_engine = $engineMap[$ContainerEngine]
        container_name = $ContainerName
        service_name = $ServiceName
        restart_command = $RestartCommand
        debug = [bool]$DiagnosticsEnabled
    }
    $configPath = Join-Path $payloadDir 'config.json'
    $configJson = $config | ConvertTo-Json -Depth 8
    [System.IO.File]::WriteAllText($configPath, $configJson, (New-Object System.Text.UTF8Encoding($false)))
    $result = Invoke-CapturedProcess -FileName $python -Arguments @($managerPath,'--config',$configPath) -Environment $environment
    if ($result.ExitCode -ne 0) {
        [Console]::Error.WriteLine(('VUT AI Tutor universal installer failed with exit code {0}. Report: {1}' -f $result.ExitCode,$resolvedReport))
        exit $result.ExitCode
    }
    Write-Host ('[PASS] Operation {0} completed. Report: {1}' -f $Action,$resolvedReport)
}
finally {
    if ($KeepPayloadDirectory) { Write-Host ('[INFO] Embedded payload directory retained: {0}' -f $payloadDir) }
    elseif (Test-Path -LiteralPath $payloadDir) { Remove-Item -LiteralPath $payloadDir -Recurse -Force -ErrorAction SilentlyContinue }
}
